CREATE TABLE "app_settings" ("key" TEXT NOT NULL, "value" TEXT NOT NULL, PRIMARY KEY ("key"));
CREATE TABLE "audio_observations" ("id" TEXT NOT NULL, "recording_id" TEXT NOT NULL REFERENCES audio_recordings (id), "position_ms" INTEGER NOT NULL, "note" TEXT NOT NULL, "created_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "audio_recordings" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "relative_path" TEXT NOT NULL UNIQUE, "state" TEXT NOT NULL CHECK (state IN ('pending','finalized','unavailable')), "microphone_check" INTEGER NOT NULL DEFAULT 0 CHECK ("microphone_check" IN (0, 1)), "interrupted" INTEGER NOT NULL DEFAULT 0 CHECK ("interrupted" IN (0, 1)), "input_id" TEXT NOT NULL, "input_name" TEXT NOT NULL, "duration_ms" INTEGER NOT NULL DEFAULT 0, "sample_rate" INTEGER NOT NULL DEFAULT 0, "channels" INTEGER NOT NULL DEFAULT 0, "byte_count" INTEGER NOT NULL DEFAULT 0, "peak_db" REAL NULL, "rms_db" REAL NULL, "status_note" TEXT NOT NULL DEFAULT '', "created_utc_ms" INTEGER NOT NULL, "finalized_utc_ms" INTEGER NULL, "context_key" TEXT NOT NULL DEFAULT '', PRIMARY KEY ("id"));
CREATE TABLE "debate_stages" ("session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "stage_key" TEXT NOT NULL, "status" TEXT NOT NULL CHECK (status IN ('pending','active','completed','skipped')), "fields" TEXT NOT NULL DEFAULT '{}', "elapsed_ms" INTEGER NOT NULL DEFAULT 0, "finished_utc_ms" INTEGER NULL, PRIMARY KEY ("session_id", "stage_key"));
CREATE TABLE "debate_workspaces" ("session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "position" TEXT NOT NULL, "response_kind" TEXT NOT NULL, "preset" TEXT NOT NULL, "current_stage" INTEGER NOT NULL DEFAULT 0, "assessments" TEXT NOT NULL DEFAULT '{}', "review_note" TEXT NOT NULL DEFAULT '', PRIMARY KEY ("session_id"));
CREATE TABLE "impromptu_queues" ("pool_key" TEXT NOT NULL, "remaining" TEXT NOT NULL, "last_question" TEXT NOT NULL, PRIMARY KEY ("pool_key"));
CREATE TABLE "impromptu_workspaces" ("session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "request_key" TEXT NOT NULL UNIQUE, "parent_session_id" TEXT NULL UNIQUE REFERENCES practice_sessions (id), "improvement" TEXT NOT NULL DEFAULT '', "response_kind" TEXT NOT NULL, "preset" TEXT NOT NULL, "view_step" TEXT NOT NULL DEFAULT 'reveal', "preparation" TEXT NOT NULL DEFAULT '', "scaffold_enabled" INTEGER NOT NULL DEFAULT 0 CHECK ("scaffold_enabled" IN (0, 1)), "scaffold" TEXT NOT NULL DEFAULT '{}', "assessments" TEXT NOT NULL DEFAULT '{}', "reflection" TEXT NOT NULL DEFAULT '', "confidence" INTEGER NULL, PRIMARY KEY ("session_id"));
CREATE TABLE "memory_speeches" ("id" TEXT NOT NULL, "draft" TEXT NOT NULL, "updated_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "memory_versions" ("id" TEXT NOT NULL, "speech_id" TEXT NOT NULL REFERENCES memory_speeches (id), "version_number" INTEGER NOT NULL, "content" TEXT NOT NULL, "created_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"), UNIQUE ("speech_id", "version_number"));
CREATE TABLE "memory_workspaces" ("session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "version_id" TEXT NOT NULL REFERENCES memory_versions (id), "section_id" TEXT NOT NULL, "mode" TEXT NOT NULL, "recall_kind" TEXT NOT NULL, "cue_stage" TEXT NOT NULL, "assistance" TEXT NOT NULL, "assessments" TEXT NOT NULL DEFAULT '{}', "review_note" TEXT NOT NULL DEFAULT '', "later_review" INTEGER NOT NULL DEFAULT 0 CHECK ("later_review" IN (0, 1)), PRIMARY KEY ("session_id"));
CREATE TABLE "practice_sessions" ("id" TEXT NOT NULL, "exercise_id" TEXT NOT NULL, "exercise_version" INTEGER NOT NULL, "module_id" TEXT NOT NULL, "snapshot" TEXT NOT NULL, "status" TEXT NOT NULL CHECK (status IN ('draft','running','paused','interrupted','completed','abandoned')), "stage" TEXT NOT NULL CHECK (stage IN ('prepare','respond','reflect')), "created_utc_ms" INTEGER NOT NULL, "updated_utc_ms" INTEGER NOT NULL, "started_utc_ms" INTEGER NULL, "completed_utc_ms" INTEGER NULL, "local_practice_date" TEXT NOT NULL, "original_offset_minutes" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "reading_workspaces" ("session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "key_results" TEXT NULL, "revision_answers" TEXT NOT NULL DEFAULT '{}', "ratings" TEXT NOT NULL DEFAULT '{}', "view_step" TEXT NOT NULL DEFAULT 'passage', "hide_passage" INTEGER NOT NULL DEFAULT 0 CHECK ("hide_passage" IN (0, 1)), "updated_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("session_id"));
CREATE TABLE "responses" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL UNIQUE REFERENCES practice_sessions (id), "body" TEXT NOT NULL DEFAULT '', "updated_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "review_records" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL UNIQUE REFERENCES practice_sessions (id), "status" TEXT NOT NULL CHECK (status IN ('inProgress','reviewed')), "notes" TEXT NOT NULL, "updated_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("id"));
CREATE TABLE "timing_segments" ("id" TEXT NOT NULL, "session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "stage" TEXT NOT NULL, "started_utc_ms" INTEGER NOT NULL, "checkpoint_utc_ms" INTEGER NOT NULL, "ended_utc_ms" INTEGER NULL, "elapsed_ms" INTEGER NOT NULL CHECK (elapsed_ms >= 0), "end_reason" TEXT NULL, PRIMARY KEY ("id"));
CREATE TABLE "writing_workspaces" ("session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "root_session_id" TEXT NOT NULL REFERENCES practice_sessions (id), "parent_session_id" TEXT NULL UNIQUE REFERENCES practice_sessions (id), "version_number" INTEGER NOT NULL, "outline" TEXT NOT NULL DEFAULT '', "audience" TEXT NOT NULL, "purpose" TEXT NOT NULL, "view_step" TEXT NOT NULL DEFAULT 'brief', "assessments" TEXT NOT NULL DEFAULT '{}', "review_rubric" TEXT NOT NULL, "legacy_review_notes" TEXT NOT NULL DEFAULT '', "next_action" TEXT NOT NULL DEFAULT '', "updated_utc_ms" INTEGER NOT NULL, PRIMARY KEY ("session_id"), UNIQUE ("root_session_id", "version_number"));
CREATE UNIQUE INDEX one_open_segment ON timing_segments(session_id) WHERE ended_utc_ms IS NULL;
PRAGMA user_version = 8;
